  const group = new Group();

  // Scene placement
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Design tokens
  const inkHex = '#16161d';
  const surfaceHex = '#0b0b10';
  const paperHex = '#e8ecf2';
  const accentHex = '#ff2a38';

  // Atlas region
  const atlas = config.atlasRegion || { x: 0, y: 0, w: 512, h: 320 };
  const atlasAspect = atlas.w / atlas.h;

  // Plane dimensions
  const planeWidth = 1.6;
  const planeHeight = planeWidth / atlasAspect;

  // Load texture
  let tex = null;
  if (config.assets?.imageUrl) {
    tex = ctx.textureLoader(config.assets.imageUrl);
  }

  // Determine texture dimensions for UV remapping
  const texW = (tex && tex.image) ? tex.image.width : atlas.w;
  const texH = (tex && tex.image) ? tex.image.height : atlas.h;

  // UV remap range
  const uMin = atlas.x / texW;
  const uMax = (atlas.x + atlas.w) / texW;
  const vMin = atlas.y / texH;
  const vMax = (atlas.y + atlas.h) / texH;

  // TSL color constants
  const inkVec = vec3(float(0x16/255), float(0x16/255), float(0x1d/255));
  const surfaceVec = vec3(float(0x0b/255), float(0x0b/255), float(0x10/255));
  const accentVec = vec3(float(0xff/255), float(0x2a/255), float(0x38/255));

  // Engineered gradient: surface at bottom, ink at top
  const gradientColor = mix(surfaceVec, inkVec, uv().y);

  // Subtle grain
  const grainUV = mul(uv(), vec2(float(350.0), float(220.0)));
  const grainVal = sub(random(floor(grainUV)), float(0.5)).mul(float(0.04));
  const grainVec = vec3(grainVal, grainVal, grainVal);

  // Combine gradient + grain
  let baseColor = add(gradientColor, grainVec);

  // Texture overlay
  if (tex) {
    const remappedU = mix(float(uMin), float(uMax), uv().x);
    const remappedV = mix(float(vMin), float(vMax), uv().y);
    const remappedUV = vec2(remappedU, remappedV);

    const texSample = texture(tex, remappedUV);
    const texAlpha = texSample.a.mul(float(0.12));
    baseColor = mix(baseColor, vec3(texSample.r, texSample.g, texSample.b), texAlpha);
  }

  // Engineered accent line at bottom edge
  const accentLine = step(float(0.03), uv().y).oneMinus();
  // Actually, step(0.03, uv().y) gives 1 when y > 0.03, so oneMinus gives 1 when y < 0.03
  // Let me use: 1.0 - step(0.03, uv().y) which is step(uv().y, 0.03) but that's different
  // Let me use sub(float(1.0), step(float(0.03), uv().y))
  const accentMask = sub(float(1.0), step(float(0.03), uv().y));
  baseColor = mix(baseColor, accentVec, accentMask.mul(float(0.3)));

  // Material
  const material = new MeshBasicNodeMaterial();
  material.colorNode = vec4(baseColor, float(0.95));
  material.transparent = true;
  material.side = DoubleSide;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const plane = new Mesh(geometry, material);
  plane.renderOrder = 1;
  group.add(plane);

  // Text rendering via MSDF
  const textContent = config.textContent || 'Pricing 3';
  let textMesh = null;

  const textConfig = {
    text: textContent,
    font: 'Lora',
    weight: 400,
    size: 0.34,
    color: paperHex,
    letterSpacing: 0.015,
    anchor: 'center',
    anchorY: 'middle'
  };

  try {
    textMesh = createTextMesh(ctx.fontAtlas, textConfig);
  } catch (e) {
    try {
      if (typeof ctx.fontAtlas === 'function') {
        textMesh = ctx.fontAtlas(textConfig);
      } else if (ctx.fontAtlas.createText) {
        textMesh = ctx.fontAtlas.createText(textConfig);
      } else if (ctx.fontAtlas.build) {
        textMesh = ctx.fontAtlas.build(textConfig);
      }
    } catch (e2) {}
  }

  if (textMesh) {
    textMesh.position.set(0, 0, 0.01);
    textMesh.renderOrder = 2;
    group.add(textMesh);
  }

  // Event handlers (none - static)
  group.userData.handlers = {};

  // Cleanup
  const disposables = [geometry, material];
  group.userData.cleanup = () => {
    gsap.killTweensOf(group);
    gsap.killTweensOf(plane);
    if (textMesh) gsap.killTweensOf(textMesh);

    disposables.forEach(d => { if (d && d.dispose) d.dispose(); });

    if (textMesh) {
      textMesh.traverse(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  };

  return group;
}
